    def _build_inspired_prompt_hints(self, patterns: set[str]) -> list[str]:
        if not self._supports_inspired_creation(patterns):
            return []
        hints = [
            "Use the source only as style, rhythm, POV, pacing, scene-density, and emotional-temperature guidance.",
            "Generate an independent new story with new names, organizations, event chain, core conflict, and world rules.",
        ]
        if patterns.intersection({
            "obsidian_galley_scene_compile_gate",
            "obsidian_storyteller_world_timeline_gate",
            "obsidian_novelsmith_scene_version_graph_gate",
            "obsidian_draft_bench_scene_history_compile_gate",
            "obsidian_textflow_context_flow_guard_gate",
        }):
            hints.append("For same-type prompts, state scene-card/version/compile scope, selected Obsidian-style context flow, and required distance from the source manuscript before drafting.")
        if "deeplore_lore_retrieval_gap_graph_gate" in patterns:
            hints.append("For same-type prompts, include target lore retrieval gates and gap-graph ids; source world-info keywords may inspire categories only, not names or facts.")
        if "writer_studio_binder_voice_rag_gate" in patterns:
            hints.append("For same-type prompts, separate Binder outline, manuscript draft, voice guide, RAG references, and plagiarism checks into visible stages before drafting.")
        if "copilot_webnovel_research_runner_gate" in patterns:
            hints.append("For chapter prompts, require research packet, plan.md equivalent, running summary, character voice files, and scene weight before the runner writes.")
        if "tinystyler_meaning_preserving_style_transfer_gate" in patterns:
            hints.append("For style-transfer-inspired prompts, name the allowed abstract style axes and the meaning-preservation test; do not request protected-author mimicry.")
        if "stylevec_style_signal_overfit_boundary_gate" in patterns:
            hints.append("For style-vector-inspired prompts, treat style similarity as an audit signal with corpus custody notes and overfit warnings, not as a generation target.")
        if "chapter_translation_style_context_gate" in patterns:
            hints.append("For translation-style continuation prompts, include chapter-level context, glossary/term map, and review checkpoint while keeping source text out of same-type drafting.")
        if "slima_book_mcp_beta_reader_file_gate" in patterns:
            hints.append("For book-MCP prompts, state book id, file path, allowed read/search/write scope, beta-reader persona, and human acceptance gate before any file mutation.")
        if "dialogoi_filetype_rag_novel_project_gate" in patterns:
            hints.append("For RAG prompts, declare whether retrieval can see content, settings, instructions, or both, and require source file class in every cited note.")
        if "scrivener_mcp_direct_project_edit_boundary_gate" in patterns:
            hints.append("For Scrivener-style project prompts, request pacing/structure diagnostics as derived notes first; direct project edits need an accepted patch envelope.")
        if "vector_story_frame_coordinate_gate" in patterns:
            hints.append("For frame-coordinate prompts, fill story beat, tone, density, register, and word-count target as abstract controls before generating prose.")
        if "setting_runtime_document_architecture_gate" in patterns:
            hints.append("For resumed setting prompts, include a session start packet listing story bible, voice bible, tracked items, scenario, and anti-pattern docs loaded.")
        if "inkfoundry_state_db_redteam_voice_sandbox_gate" in patterns:
            hints.append("For long-form generation prompts, make StateDB facts outrank RAG and route contradictions to RedTeam/VoiceSandbox review before drafting.")
        if "robot_writers_room_human_card_flow_gate" in patterns:
            hints.append("For human-card ideation prompts, ask for candidate idea cards with final-say decision slots, not autonomous canon changes.")
        if "spire_roleplay_character_privacy_fiction_surface_gate" in patterns:
            hints.append("For roleplay-derived fiction prompts, state OOC/IC scope, character privacy class, wiki source class, and chapter/review visibility before generation.")
        if "ai_book_generator_agent_mode_local_key_export_gate" in patterns:
            hints.append("For book-agent prompts, declare the current stage, local-key/storage exclusion, export target, cancel behavior, and accepted-output checkpoint before drafting.")
        if "risuai_lorebook_prompt_order_regex_gate" in patterns:
            hints.append("For lorebook prompts, list activation keys, insertion order, regex rewrite rules, variables, and impersonation boundaries as reviewable metadata.")
        if "grimodex_codex_attribution_scene_chat_gate" in patterns:
            hints.append("For scene-chat prompts, request origin labels and extraction candidates before writing; accepted Codex facts must cite source chat ids and reviewer decisions.")
        if "supernovel_architecture_blueprint_state_search_gate" in patterns:
            hints.append("For long-form prompts, declare whether the task is architecture, chapter blueprint, chapter draft, or finalization, and include state-search contradiction findings.")
        if "screenplay_realtime_writers_room_media_boundary_gate" in patterns:
            hints.append("For writers-room prompts, include current beat pointer, Director notes, mutable character schema changes, and media/attachment exclusions.")
        if "nebula_codex_character_knowledge_version_gate" in patterns:
            hints.append("For Codex-memory prompts, ask for character knowledge state, chapter version id, extracted-entity provenance, and consistency-check result before rewrite.")
        if "forfiction_theia_story_extension_skill_gate" in patterns:
            hints.append("For Theia-style prompts, list story-memory variables, story-preferences, editor selection, agent role, and skill.yaml-derived contract id without copying prompt fragments.")
        if "inkos_truthfile_api_fanfic_imitation_gate" in patterns:
            hints.append("For truth-file API prompts, declare endpoint mode, rights boundary, fanfic/spinoff/imitation status, doctor result, and secrets exclusion before generation.")
        if "mock_first_multi_agent_continuation_gate" in patterns:
            hints.append("Prompt from pipeline roles as abstract duties: planner, drafter, reviewer, linter, budget auditor, and author gate; do not reuse upstream role wording or source-book facts.")
        if "truth_file_write_next_state_update_gate" in patterns:
            hints.append("Prompt with target truth-file ids, snapshot id, unresolved thread ids, and state-update schema; raw source examples stay outside drafting context.")
        if "author_control_context_assembly_gate" in patterns:
            hints.append("Prompt only with author-selected lore, fact rows, and summary layers; include an excluded-context list to prevent accidental source drift.")
        if "craft_scene_concrete_finding_revision_gate" in patterns:
            hints.append("Prompt scene review to return concrete findings with locations, narrative function, realism/access limits, and style-bearing details before asking for rewrite.")
        if "tutorial_case_library_curation_gate" in patterns:
            hints.append("Prompt tutorial/case lessons as principle ids and case-dimension tags, not as copied article text or benchmark-novel prose.")
        if "anti_hallucination_strand_weave_review_gate" in patterns:
            hints.append("Prompt serial review with outline-law, setting-physics, new-entity, and strand-balance checks tied to the target book's accepted canon.")
        if "ai_flavor_template_shell_cleanup_gate" in patterns:
            hints.append("Prompt AI-flavor cleanup as a constrained edit pass with preserved facts, preserved tone, and explicit removed template-shell categories.")
        if "hierarchical_narrative_memory_os_gate" in patterns:
            hints.append("Prompt with target-story memory layers: bible, canon facts, vector recall, structured state, constraint graph, and world-simulation consequences; source layer names may guide format only.")
        if "narrative_canon_version_branch_graph_gate" in patterns:
            hints.append("Prompt alternate branches with branch id, divergence event, merge policy, and paradox-resolution criteria before generating same-type or what-if prose.")
        if "planner_writer_evaluator_editor_saga_gate" in patterns:
            hints.append("Prompt planner/writer/evaluator/editor as duties with independent outputs and finalization status; do not copy upstream agent wording or source canon facts.")
        if "story_weaver_kg_bible_rag_gate" in patterns:
            hints.append("Prompt continuity review to cite Story Bible, graph edge, vector/RAG hit, event timeline, or universe rule for every finding.")
        if "taleforge_memory_continuity_research_gate" in patterns:
            hints.append("Prompt research assistant output as provenance-tagged realism notes; continuity guardian findings need conflict location and living-bible update proposal.")
        if "agents_room_multistep_story_collaboration_gate" in patterns:
            hints.append("Prompt specialized duties as target-story subtasks only; source prompts and human-written stories remain excluded examples, not drafting context.")
        if "judgemark_literary_criteria_calibration_gate" in patterns:
            hints.append("Prompt literary criteria as a target scorecard; do not import benchmark passages, judge examples, or leaderboard outputs into the new story.")
        if "seven_law_platform_closed_loop_gate" in patterns:
            hints.append("Prompt seven-law and platform-fit checks as target-story review dimensions; do not copy upstream command wording or platform examples.")
        if "vibe_noveling_skill_agent_save_cat_gate" in patterns:
            hints.append("Prompt Save-the-Cat beats, booming expansion, and consistency guard as abstract duties with target-story ids only.")
        if "story_bible_qa_pov_lore_rule_gate" in patterns:
            hints.append("Prompt continuity QA to cite target Story Bible, POV, location, and lore-rule evidence ids for every finding.")
        if "gemini_writer_context_recovery_gate" in patterns:
            hints.append("Prompt autonomous writing runs with explicit stop/resume checkpoints, context-summary ids, and allowed workspace actions; provider/runtime details remain excluded.")
        if "wikiplots_plot_corpus_boundary_gate" in patterns:
            hints.append("Prompt source deconstruction to output abstract plot mechanics, not Wikipedia plot rows, story titles, or corpus examples.")
        if "reliquery_reconstructive_recall_vault_gate" in patterns:
            hints.append("Prompt memory retrieval as questions over target relics and relationships; retrieved snippets must be cited and may not silently become new canon.")
        if "novel_studio_accepted_chapter_memory_gate" in patterns:
            hints.append("Prompt drafting from a visible Context Pack with Story Bible, Style Bible, recent accepted summaries, character states, graph facts, and excluded draft-only material.")
        if "novelforge_version_safe_human_review_gate" in patterns:
            hints.append("Prompt every generated or revised scene as a candidate version with proposed facts and continuity warnings, never as an overwrite of accepted prose.")
        if "unorthodox_pipeline_stage_retry_gate" in patterns:
            hints.append("Prompt each stage with its gate contract, retry budget, rolling synopsis, previous-tail bridge, and explicit abort conditions for canon drift or AI artifacts.")
        if "writeros_role_validator_boundary_gate" in patterns:
            hints.append("Prompt specialized validators as target-story roles only: plot, entity graph, psychology arc, travel/spatial logic, and rules mechanics; upstream proprietary code remains excluded.")
        if "harnessnovel_deconstruct_imitate_gate" in patterns:
            hints.append("Prompt source study to output abstract deconstruction cards for outline function, world rules, pacing, emotion beats, and style axes; never draft from raw reference text.")
        if "novel_rule_auditor_learning_loop_gate" in patterns:
            hints.append("Prompt rule auditing before and after continuation: compare draft/final deltas, name repeated errors, propose rule updates, and require author approval before reuse.")
        if "novel_rewriter_copyright_cost_gate" in patterns:
            hints.append("Prompt rewriting with explicit similarity/copyright check, de-AI pass, quality threshold, per-chapter budget, and fallback-provider exclusion from creative content.")
        if "woke_novel_template_resume_cli_gate" in patterns:
            hints.append("Prompt each workflow step as a target template id plus artifact contract and resume cursor; upstream step prompts and CLI command text remain excluded.")
        if "nai_multi_agent_rag_consistency_gate" in patterns:
            hints.append("Prompt multi-agent consistency as independent target-story reviewer roles with cited retrieval metadata, then merge only approved findings into the new outline or continuation plan.")
